<?php
 namespace Slim\Http; class Util { public static function stripSlashesIfMagicQuotes($rawData, $overrideStripSlashes = null) { $strip = is_null($overrideStripSlashes) ? get_magic_quotes_gpc() : $overrideStripSlashes; if ($strip) { return self::stripSlashes($rawData); } return $rawData; } protected static function stripSlashes($rawData) { return is_array($rawData) ? array_map(array('self', 'stripSlashes'), $rawData) : stripslashes($rawData); } public static function encrypt($data, $key, $iv, $settings = array()) { if ($data === '' || !extension_loaded('mcrypt')) { return $data; } $defaults = array( 'algorithm' => MCRYPT_RIJNDAEL_256, 'mode' => MCRYPT_MODE_CBC ); $settings = array_merge($defaults, $settings); $module = mcrypt_module_open($settings['algorithm'], '', $settings['mode'], ''); $ivSize = mcrypt_enc_get_iv_size($module); if (safe_strlen($iv) > $ivSize) { $iv = substr($iv, 0, $ivSize); } $keySize = mcrypt_enc_get_key_size($module); if (safe_strlen($key) > $keySize) { $key = substr($key, 0, $keySize); } mcrypt_generic_init($module, $key, $iv); $res = @mcrypt_generic($module, $data); mcrypt_generic_deinit($module); return $res; } public static function decrypt($data, $key, $iv, $settings = array()) { if ($data === '' || !extension_loaded('mcrypt')) { return $data; } $defaults = array( 'algorithm' => MCRYPT_RIJNDAEL_256, 'mode' => MCRYPT_MODE_CBC ); $settings = array_merge($defaults, $settings); $module = mcrypt_module_open($settings['algorithm'], '', $settings['mode'], ''); $ivSize = mcrypt_enc_get_iv_size($module); if (safe_strlen($iv) > $ivSize) { $iv = substr($iv, 0, $ivSize); } $keySize = mcrypt_enc_get_key_size($module); if (safe_strlen($key) > $keySize) { $key = substr($key, 0, $keySize); } mcrypt_generic_init($module, $key, $iv); $decryptedData = @mdecrypt_generic($module, $data); $res = rtrim($decryptedData, "\0"); mcrypt_generic_deinit($module); return $res; } public static function serializeCookies(\Slim\Http\Headers &$headers, \Slim\Http\Cookies $cookies, array $config) { if ($config['cookies.encrypt']) { foreach ($cookies as $name => $settings) { if (is_string($settings['expires'])) { $expires = safe_strtotime($settings['expires']); } else { $expires = (int) $settings['expires']; } $settings['value'] = static::encodeSecureCookie( $settings['value'], $expires, $config['cookies.secret_key'], $config['cookies.cipher'], $config['cookies.cipher_mode'] ); static::setCookieHeader($headers, $name, $settings); } } else { foreach ($cookies as $name => $settings) { static::setCookieHeader($headers, $name, $settings); } } } public static function encodeSecureCookie($value, $expires, $secret, $algorithm, $mode) { $key = hash_hmac('sha1', (string) $expires, $secret); $iv = self::getIv($expires, $secret); $secureString = base64_encode( self::encrypt( $value, $key, $iv, array( 'algorithm' => $algorithm, 'mode' => $mode ) ) ); $verificationString = hash_hmac('sha1', $expires . $value, $key); return implode('|', array($expires, $secureString, $verificationString)); } public static function decodeSecureCookie($value, $secret, $algorithm, $mode) { if ($value) { $value = safe_explode('|', $value); if (count($value) === 3 && ((int) $value[0] === 0 || (int) $value[0] > time())) { $key = hash_hmac('sha1', $value[0], $secret); $iv = self::getIv($value[0], $secret); $data = self::decrypt( base64_decode($value[1]), $key, $iv, array( 'algorithm' => $algorithm, 'mode' => $mode ) ); $verificationString = hash_hmac('sha1', $value[0] . $data, $key); if ($verificationString === $value[2]) { return $data; } } } return false; } public static function setCookieHeader(&$header, $name, $value) { if (is_array($value)) { $domain = ''; $path = ''; $expires = ''; $secure = ''; $httponly = ''; if (isset($value['domain']) && $value['domain']) { $domain = '; domain=' . $value['domain']; } if (isset($value['path']) && $value['path']) { $path = '; path=' . $value['path']; } if (isset($value['expires'])) { if (is_string($value['expires'])) { $timestamp = safe_strtotime($value['expires']); } else { $timestamp = (int) $value['expires']; } if ($timestamp !== 0) { $expires = '; expires=' . gmdate('D, d-M-Y H:i:s e', $timestamp); } } if (isset($value['secure']) && $value['secure']) { $secure = '; secure'; } if (isset($value['httponly']) && $value['httponly']) { $httponly = '; HttpOnly'; } $cookie = sprintf('%s=%s%s', urlencode($name), urlencode((string) $value['value']), $domain . $path . $expires . $secure . $httponly); } else { $cookie = sprintf('%s=%s', urlencode($name), urlencode((string) $value)); } if (!isset($header['Set-Cookie']) || $header['Set-Cookie'] === '') { $header['Set-Cookie'] = $cookie; } else { $header['Set-Cookie'] = implode("\n", array($header['Set-Cookie'], $cookie)); } } public static function deleteCookieHeader(&$header, $name, $value = array()) { $cookiesOld = array(); $cookiesNew = array(); if (isset($header['Set-Cookie'])) { $cookiesOld = safe_explode("\n", $header['Set-Cookie']); } foreach ($cookiesOld as $c) { if (isset($value['domain']) && $value['domain']) { $regex = sprintf('@%s=.*domain=%s@', urlencode($name), preg_quote($value['domain'])); } else { $regex = sprintf('@%s=@', urlencode($name)); } if (preg_match($regex, $c) === 0) { $cookiesNew[] = $c; } } if ($cookiesNew) { $header['Set-Cookie'] = implode("\n", $cookiesNew); } else { unset($header['Set-Cookie']); } self::setCookieHeader($header, $name, array_merge(array('value' => '', 'path' => null, 'domain' => null, 'expires' => time() - 100), $value)); } public static function parseCookieHeader($header) { $cookies = array(); $header = rtrim($header, "\r\n"); $headerPieces = preg_split('@\s*[;,]\s*@', $header); foreach ($headerPieces as $c) { $cParts = safe_explode('=', $c, 2); if (count($cParts) === 2) { $key = urldecode($cParts[0]); $value = urldecode($cParts[1]); if (!isset($cookies[$key])) { $cookies[$key] = $value; } } } return $cookies; } private static function getIv($expires, $secret) { $data1 = hash_hmac('sha1', 'a'.$expires.'b', $secret); $data2 = hash_hmac('sha1', 'z'.$expires.'y', $secret); return pack("h*", $data1.$data2); } } 